   460|/** Extract a relevant section of a large file based on goal keywords.
   461| * Instead of sending the first N chars (which may miss the target code),
   462| * search for lines containing goal keywords and return a window around
   463| * the best match. Falls back to head+tail if no keywords match. */
   464|function extractRelevantSection(content: string, goal: string, maxChars: number): string {
   465|  const lines = content.split('\n');
   466|  const goalWords = goal.toLowerCase()
   467|    .replace(/[^a-z0-9\s]/g, ' ')
   468|    .split(/\s+/)
   469|    .filter((w) => w.length >= 4)
   470|    .filter((w) => !['that', 'this', 'with', 'from', 'have', 'please', 'change', 'deploy', 'anything', 'current', 'status', 'label', 'version', 'endpoint', 'route', 'field'].includes(w));
   471|
   472|  if (goalWords.length === 0) {
   473|    return truncate(content, maxChars);
   474|  }
   475|
   476|  // Score each line by how many goal words it contains
   477|  let bestLineIdx = 0;
   478|  let bestScore = 0;
   479|  for (let i = 0; i < lines.length; i++) {
   480|    const lower = lines[i].toLowerCase();
   481|    let score = 0;
   482|    for (const w of goalWords) {
   483|      if (lower.includes(w)) score += 1;
   484|    }
   485|    if (score > bestScore) {
   486|      bestScore = score;
   487|      bestLineIdx = i;
   488|    }
   489|  }
   490|
   491|  if (bestScore === 0) {
   492|    // No keyword match — send head + tail so the LLM sees imports and exports
   493|    const headChars = Math.floor(maxChars * 0.6);
   494|    const tailChars = maxChars - headChars;
   495|    const head = truncate(content, headChars);
   496|    const tail = content.length > tailChars ? content.slice(-tailChars) : '';
   497|    return head + '\n\n... [middle section omitted for length] ...\n\n' + tail;
   498|  }
   499|
   500|  // Return a window of lines around the best match
   501|  const contextLines = 60; // ~60 lines before and after the match
   502|  const startLine = Math.max(0, bestLineIdx - contextLines);
   503|    const endLine = Math.min(lines.length, bestLineIdx + contextLines);
   504|  const section = lines.slice(startLine, endLine).join('\n');
   505|  const prefix = startLine > 0 ? `... [lines 1-${startLine} omitted] ...\n` : '';
   506|  const suffix = endLine < lines.length ? `\n... [lines ${endLine + 1}-${lines.length} omitted] ...` : '';
   507|  const result = prefix + section + suffix;
   508|  return truncate(result, maxChars);
   509|}
