   596|async function runCommand(cwd: string, command: string): Promise<IVXAutonomousCoderTestResult> {
   597|  const started = Date.now();
   598|  // Resolve the runtime: the Render container runs under node+tsx, not bun.
   599|  // `bun test` and `bun x tsc` fail with ENOENT on the production container, so
   600|  // we resolve the runtime via resolveRuntimeCommand and translate the command
   601|  // to its node-based equivalent when bun is not available.
   602|  const parts = command.split(/\s+/);
   603|  const requestedRuntime = parts[0] as 'bun' | 'bunx' | 'node' | 'npx';
   604|  const resolution = resolveRuntimeCommand(requestedRuntime);
   605|  let effectiveCmd = resolution.resolvedPath ?? resolution.effectiveCommand;
   606|  let effectiveArgs = parts.slice(1);
   607|  let displayCommand = command;
   608|  // When bun falls back to node, translate `bun test <file>` → `node --test <file>`
   609|  // (node:test runner) and `bun x tsc --noEmit` → `npx tsc --noEmit` (or node tsc).
   610|  if (resolution.usedFallback && requestedRuntime === 'bun') {
   611|    if (effectiveArgs[0] === 'test') {
   612|      effectiveArgs = ['--test', ...effectiveArgs.slice(1)];
   613|      displayCommand = `node --test ${effectiveArgs.slice(1).join(' ')}`;
   614|    } else if (effectiveArgs[0] === 'x') {
   615|      // `bun x tsc` → use npx instead (with --yes so it never waits for confirmation)
   616|      const npxRes = resolveRuntimeCommand('npx');
   617|      effectiveCmd = npxRes.resolvedPath ?? npxRes.effectiveCommand;
   618|      effectiveArgs = ['--yes', ...effectiveArgs.slice(1)]; // drop the 'x', add --yes
   619|      displayCommand = `npx ${effectiveArgs.join(' ')}`;
   620|    }
   621|  }
   622|  try {
   623|    const result = await execFileAsync(effectiveCmd, effectiveArgs, {
   624|      cwd,
   625|      timeout: COMMAND_TIMEOUT_MS,
   626|      maxBuffer: 1024 * 1024 * 4,
   627|      env: { ...process.env, CI: '1', FORCE_COLOR: '0' },
   628|    });
   629|    return {
   630|      command: displayCommand,
   631|      ok: true,
   632|      exitCode: 0,
   633|      stdoutTail: truncate(typeof result.stdout === 'string' ? result.stdout : '', 2000),
   634|      stderrTail: truncate(typeof result.stderr === 'string' ? result.stderr : '', 2000),
   635|      durationMs: Date.now() - started,
   636|    };
   637|  } catch (error) {
   638|    const err = error as { code?: number; stdout?: string; stderr?: string; signal?: string };
   639|    return {
   640|      command: displayCommand,
   641|      ok: false,
   642|      exitCode: typeof err.code === 'number' ? err.code : null,
   643|      stdoutTail: truncate(typeof err.stdout === 'string' ? err.stdout : '', 2000),
   644|      stderrTail: truncate(typeof err.stderr === 'string' ? err.stderr : '', 2000),
   645|      durationMs: Date.now() - started,
   646|    };
   647|  }
