   727|function parseLLMPatchResponse(response: string): { rootCause: string; technicalPlan: string; operations: IVXAutonomousCoderPatchOperation[] } | null {
   728|  try {
   729|    // Strip markdown code fences if present (be aggressive — LLMs love fences)
   730|    const cleaned = response.replace(/```json\s*/gi, '').replace(/```\s*/g, '').trim();
