   732|    const start = cleaned.indexOf('{');
   733|    const end = cleaned.lastIndexOf('}');
   734|    if (start < 0 || end < 0 || end <= start) return null;
   735|    let jsonStr = cleaned.slice(start, end + 1);
   736|    let parsed: { rootCause?: string; technicalPlan?: string; operations?: Array<{ path?: string; kind?: string; oldText?: string; newText?: string; reason?: string }> };
   737|    try {
   738|      parsed = JSON.parse(jsonStr);
   739|    } catch {
   740|      // Permissive fallback: strip trailing commas + fix smart quotes LLMs sometimes emit
   741|      const fixed = jsonStr
   742|        .replace(/,\s*([}\]])/g, '$1')
   743|        .replace(/[\u201c\u201d]/g, '"')
   744|        .replace(/[\u2018\u2019]/g, "'");
   745|      parsed = JSON.parse(fixed);
   746|    }
   747|    if (!Array.isArray(parsed.operations)) return null;
   748|    const operations: IVXAutonomousCoderPatchOperation[] = [];
   749|    for (const op of parsed.operations) {
   750|      if (typeof op.path !== 'string' || typeof op.kind !== 'string') continue;
   751|      if (op.kind !== 'replace_exact' && op.kind !== 'create_file') continue;
   752|      if (typeof op.oldText !== 'string' || typeof op.newText !== 'string') continue;
   753|      operations.push({
   754|        path: op.path,
   755|        kind: op.kind,
   756|        oldText: op.oldText,
   757|        newText: op.newText,
   758|        reason: typeof op.reason === 'string' ? op.reason : '',
   759|      });
   760|    }
   761|    // Empty operations is valid when the LLM signals "already satisfied" — return it so the loop exits cleanly (no phantom patch)
   762|    if (operations.length === 0) {
   763|      return {
   764|        rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'no operations needed',
   765|        technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'no change required',
   766|        operations: [],
   767|      };
   768|    }
   769|    return {
   770|      rootCause: typeof parsed.rootCause === 'string' ? parsed.rootCause : 'LLM-generated patch',
   771|      technicalPlan: typeof parsed.technicalPlan === 'string' ? parsed.technicalPlan : 'Replace exact text per operations',
   772|      operations,
   773|    };
   774|  } catch {
   775|    return null;
   776|  }
