   779|/** Promise-race timeout wrapper so the LLM call can never hang the loop.
   780| * V6.19: Now also creates an AbortController and aborts it on timeout so the
   781| * underlying HTTP request is actually cancelled (Promise.race alone does NOT
   782| * cancel the fetch — the connection stays open consuming resources). */
   783|function withTimeoutAndAbort<T>(
   784|  promise: Promise<T>,
   785|  ms: number,
   786|  label: string,
   787|  abortController?: AbortController,
   788|): Promise<T> {
   789|  return Promise.race([
   790|    promise,
   791|    new Promise<T>((_, reject) => {
   792|      const timer = setTimeout(() => {
   793|        if (abortController) {
   794|          try { abortController.abort(); } catch { /* already aborted */ }
   795|        }
   796|        const err = new Error(`${label} timed out after ${ms}ms`);
   797|        err.name = 'LLMTimeoutError';
   798|        reject(err);
   799|      }, ms);
   800|      // Clear timer if promise resolves first
   801|      promise.then(
   802|        () => clearTimeout(timer),
   803|        () => clearTimeout(timer),
   804|      );
   805|    }),
   806|  ]);
   807|}
